import {esc,fmt} from '../../ui/format.js';
import {STATES,eventCSV} from '../../core/event-log.js';
const colors=['#25836d','#8c98a8','#ce8441','#b2b9c4','#6a73bc','#b99c32','#b34f5b','#475569'];
export function eventLogView(result){
 if(!result?.audits)return '<div class="notice">No complete event log in this older result. Run the model again.</div>';
 return `<section class="panel" id="event-ledger"><h2>Inspectable event log & integrity</h2><p>Full logs for every replication. Times in seconds. State totals are capacity-normalized seconds; simultaneous channels may have different states.</p><div class="row"><label>Replication<select data-ledger-rep>${result.audits.map((_,i)=>`<option value="${i}">${i+1}</option>`).join('')}</select></label><label>Event type<select data-ledger-type><option value="">All</option></select></label><label>Unit / resource / station / code<input data-ledger-search placeholder="Filter events"></label><button type="button" data-ledger-json>Export full JSON</button><button type="button" data-ledger-csv>Export filtered CSV</button></div><div data-ledger-integrity></div><div class="row"><button type="button" data-ledger-prev>Previous</button><span data-ledger-page></span><button type="button" data-ledger-next>Next</button></div><div class="tablewrap"><table><thead><tr><th># / time (s)</th><th>Event</th><th>Entity / unit</th><th>Code / detail</th></tr></thead><tbody data-ledger-rows></tbody></table></div><h3>State timeline</h3><label>Operation / resource<select data-ledger-entity></select></label><div data-ledger-timeline></div><p>Active work takes priority over an OFF calendar. Unreserved resource capacity is idle or off-shift; it is not inferred to be starved. Retained resources inherit the owning channel's busy/down/wait state. This is state accounting, not optimization advice.</p></section>`;
}
export function filterEvents(events,type='',query=''){const q=query.toLowerCase();return events.filter(e=>(!type||e.type===type)&&(!q||[e.unit,e.station,e.entity,e.resource,e.code,e.type].some(x=>String(x||'').toLowerCase().includes(q))));}
export function bindEventLog(result,download,root=document){
 const panel=root.querySelector('#event-ledger');if(!panel||!result?.audits)return;
 const get=s=>panel.querySelector(s);let page=0,current,filtered=[];
 function timeline(){const id=get('[data-ledger-entity]').value;const events=current.events.filter(e=>e.type==='state_interval'&&e.entity===id);const horizon=current.events[0].horizon,totals=current.integrity.states[id];
  if(!totals){get('[data-ledger-timeline]').innerHTML='No states';return;}
  // Render the timeline as SVG rectangles, combining adjacent identical partitions.
  const segments=[];for(const e of events){const last=segments.at(-1);if(last&&last.end===e.time&&JSON.stringify(last.counts)===JSON.stringify(e.counts))last.end=e.end;else segments.push({...e});}
  const capacity=Object.values(events[0]?.counts||{}).reduce((a,b)=>a+b,0);
  get('[data-ledger-timeline]').innerHTML=`<svg role="img" aria-label="State timeline in seconds" viewBox="0 0 1000 60" style="width:100%;height:70px">${segments.map(e=>{let y=0;return STATES.map((s,i)=>{const height=(e.counts[s]||0)/capacity*60;const rect=`<rect x="${e.time/horizon*1000}" y="${y}" width="${(e.end-e.time)/horizon*1000}" height="${height}" fill="${colors[i]}"><title>${esc(s)}: ${fmt(e.time,3)}–${fmt(e.end,3)} s; ${e.counts[s]||0} units</title></rect>`;y+=height;return rect;}).join('');}).join('')}</svg><p>0 → ${fmt(horizon)} s</p><div class="row">${STATES.map((s,i)=>`<span style="border-left:8px solid ${colors[i]};padding:5px">${esc(s)}: ${fmt(totals[s],3)} s</span>`).join('')}</div>`;
 }
 function rows(){filtered=filterEvents(current.events,get('[data-ledger-type]').value,get('[data-ledger-search]').value);const pages=Math.max(1,Math.ceil(filtered.length/100));page=Math.max(0,Math.min(page,pages-1));get('[data-ledger-page]').textContent=`${filtered.length} events · page ${page+1}/${pages}`;get('[data-ledger-prev]').disabled=page===0;get('[data-ledger-next]').disabled=page===pages-1;
  get('[data-ledger-rows]').innerHTML=filtered.slice(page*100,page*100+100).map(e=>{const {model,...detail}=e;return `<tr><td>${e.seq} / ${fmt(e.time,3)}</td><td>${esc(e.type)}</td><td>${esc(e.station||e.entity||e.resource||'')} ${esc(e.unit||'')}</td><td><details><summary>${esc(e.code||e.result||'Details')}</summary><pre>${esc(JSON.stringify(detail,null,2))}</pre></details></td></tr>`;}).join('');
 }
 function select(){current=result.audits[+get('[data-ledger-rep]').value];page=0;const integrity=current.integrity;get('[data-ledger-type]').innerHTML='<option value="">All</option>'+[...new Set(current.events.map(e=>e.type))].sort().map(t=>`<option>${esc(t)}</option>`).join('');get('[data-ledger-entity]').innerHTML=Object.keys(integrity.states).map(id=>`<option value="${esc(id)}">${esc(current.events[0].model.nodes.find(n=>n.id===id)?.name||id)} (${esc(id)})</option>`).join('');get('[data-ledger-integrity]').innerHTML=`<div class="notice"><b>${integrity.ok?'PASS':'FAIL'}</b> · ${integrity.checks.map(esc).join(' · ')}<p>${integrity.errors.map(esc).join('<br>')}</p>${integrity.warnings.map(w=>`<p>${esc(w)}</p>`).join('')}</div><details><summary>Counts by defect / reason code</summary><pre>${esc(JSON.stringify(integrity.quality,null,2))}</pre></details>`;rows();timeline();}
 get('[data-ledger-rep]').onchange=select;get('[data-ledger-type]').onchange=()=>{page=0;rows();};get('[data-ledger-search]').oninput=()=>{page=0;rows();};get('[data-ledger-prev]').onclick=()=>{page--;rows();};get('[data-ledger-next]').onclick=()=>{page++;rows();};get('[data-ledger-entity]').onchange=timeline;
 get('[data-ledger-json]').onclick=()=>download('event-log.json',JSON.stringify(current,null,2));get('[data-ledger-csv]').onclick=()=>download('event-log.csv',eventCSV(filtered),'text/csv;charset=utf-8');select();
}
